window.docContents[176].resolve({"/rules/RG1004/#RG1004-example":{"contents":"\n\nThe correction proves the same concrete equality (2 : Nat) = 2 by rfl. The violation reports both the generated axiom and its parent theorem.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1004: Compiler-trusting proofs require separate classification","header":"Checked example","id":"/rules/RG1004/#RG1004-example"},"/rules/RG2003/#RG2003-example":{"contents":"\n\nThe correction removes a dead lambda binding while preserving identity's complete natural-number behavior. No warning or linter is disabled.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2003: Claimed source must elaborate warning-free","header":"Checked example","id":"/rules/RG2003/#RG2003-example"},"/rules/RG3002/#RG3002-example":{"contents":"\n\nThe correction adds the missing equality between the reference and its replacement on the full natural-number domain, keeping the checked execution claim and both implementations.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG3002: Checked execution requires admitted correspondence","header":"Checked example","id":"/rules/RG3002/#RG3002-example"},"/rules/RG4001/#RG4001-example":{"contents":"\n\nThe correction removes the orphan marker; the positive reflexivity fence is unchanged.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4001: Documentation fences must have a valid classification","header":"Checked example","id":"/rules/RG4001/#RG4001-example"}});